mapper.update:
UPDATE sr_blog_tag
SET slug = #{slug},
    name = #{name},
    description = #{description}
WHERE id = #{id}

mapper.select:
SELECT pt.post_id AS post_id, t.id AS tag_id, t.slug AS slug, t.name AS name FROM sr_blog_post_tag pt JOIN sr_blog_tag t ON t.id = pt.tag_id WHERE pt.post_id IN
#{postId}
ORDER BY t.name ASC, t.id ASC
